import React, { useState, useContext } from 'react';
import { useLocation } from 'react-router-dom';
import FeedbackModal from './FeedbackModal';
import { FeedbackContext } from '../contexts/FeedbackContext';

const FloatingFeedbackButton: React.FC = () => {
  const [showModal, setShowModal] = useState(false);
  const location = useLocation();
  const feedbackContext = useContext(FeedbackContext);

  const handleOpenModal = () => {
    setShowModal(true);
  };

  const handleCloseModal = () => {
    setShowModal(false);
  };

  // Build context from FeedbackContext and current location
  const context = feedbackContext ? {
    storyId: feedbackContext.storyId,
    storyTitle: feedbackContext.storyTitle,
    step: feedbackContext.step,
    page: feedbackContext.page || getPageName(location.pathname),
    url: window.location.href
  } : {
    page: getPageName(location.pathname),
    url: window.location.href
  };

  return (
    <>
      <button
        onClick={handleOpenModal}
        className="btn btn-warning shadow-lg"
        style={{
          position: 'fixed',
          bottom: '20px',
          right: '20px',
          zIndex: 1030,
          borderRadius: '50%',
          width: '40px',
          height: '40px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          backgroundColor: '#FFBC00',
          borderColor: '#FFBC00',
          boxShadow: '0 4px 12px rgba(0, 0, 0, 0.15)',
          transition: 'all 0.3s ease',
          cursor: 'pointer'
        }}
        onMouseEnter={(e) => {
          e.currentTarget.style.transform = 'scale(1.1)';
          e.currentTarget.style.boxShadow = '0 6px 16px rgba(0, 0, 0, 0.2)';
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.transform = 'scale(1)';
          e.currentTarget.style.boxShadow = '0 4px 12px rgba(0, 0, 0, 0.15)';
        }}
        title="Need Help? Send Feedback"
        aria-label="Open feedback form"
      >
        <i className="fas fa-question-circle" style={{ fontSize: '24px', color: '#fff' }}></i>
      </button>

      <FeedbackModal show={showModal} onClose={handleCloseModal} context={context} />
    </>
  );
};

// Helper function to get a readable page name from pathname
const getPageName = (pathname: string): string => {
  if (pathname.includes('/create-story')) return 'Story Creation';
  if (pathname.includes('/story/') && pathname.includes('/manage')) return 'Story Management';
  if (pathname.includes('/season/') && pathname.includes('/edit')) return 'Season Edit';
  if (pathname.includes('/episode/') && pathname.includes('/manage')) return 'Episode Management';
  if (pathname.includes('/my-studio')) return 'My Studio';
  if (pathname.includes('/characters')) return 'Characters';
  if (pathname.includes('/collaborators')) return 'Collaborators';
  if (pathname.includes('/stories')) return 'Stories';
  if (pathname.includes('/studios')) return 'Studios';
  return 'Page';
};

export default FloatingFeedbackButton;
